import pandas as pd
from collections import Counter, defaultdict
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Bounded merge-aware optimizer for serialized character-Trie reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source frame and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert a value to evaluator text while preserving the original value."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
            if hasattr(missing, "item") and bool(missing.item()):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the common-prefix length using bounded binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse from lexicographically adjacent strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested column groups contiguous without dropping any columns."""
        if not col_merge:
            return list(order)

        position = {column: i for i, column in enumerate(order)}
        groups = {}
        claimed = set()

        for request in col_merge:
            request_set = set(request)
            members = [
                column
                for column in order
                if column in request_set and column not in claimed
            ]
            if not members:
                continue

            members.sort(key=position.__getitem__)
            for column in members:
                groups[column] = members
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = groups.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @staticmethod
    def _strings(text, orders):
        """Serialize every row using its supplied source-column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    @staticmethod
    def _blocks(columns, base_order, col_merge):
        """Build atomic merge blocks as integer source-column indices."""
        index = {column: i for i, column in enumerate(columns)}
        base_names = [columns[i] for i in base_order]

        if not col_merge:
            return [[i] for i in base_order]

        position = {column: i for i, column in enumerate(base_names)}
        claimed = set()
        blocks = []

        for request in col_merge:
            request_set = set(request)
            members = [
                column
                for column in base_names
                if column in request_set and column not in claimed
            ]
            if not members:
                continue

            members.sort(key=position.__getitem__)
            blocks.append([index[column] for column in members])
            claimed.update(members)

        for column in base_names:
            if column not in claimed:
                blocks.append([index[column]])

        blocks.sort(
            key=lambda block: min(position[columns[column]] for column in block)
        )
        return blocks

    def _global_candidates(self, text, columns, col_merge):
        """Create pair-frequency and repetition-frequency global order proposals."""
        n = len(text)
        m = len(columns)
        stats = []

        for column in range(m):
            counts = Counter(text[row][column] for row in range(n))
            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat_mass = sum(
                len(value) * (count - 1)
                for value, count in counts.items()
            )
            stats.append((pair_mass, repeat_mass, len(counts)))

        pair_order = sorted(
            range(m),
            key=lambda column: (
                -stats[column][0],
                -stats[column][1],
                stats[column][2],
                column,
            ),
        )
        repeat_order = sorted(
            range(m),
            key=lambda column: (
                -stats[column][1],
                -stats[column][0],
                stats[column][2],
                column,
            ),
        )

        lookup = {column: i for i, column in enumerate(columns)}
        proposals = []

        for ranking in (pair_order, repeat_order):
            names = self._merge(
                columns,
                [columns[column] for column in ranking],
                col_merge,
            )
            proposals.append([lookup[name] for name in names])

        return proposals, pair_order

    def _conditional(self, text, columns, col_merge, global_order):
        """Build a bounded conditional prefix partition over atomic merge blocks."""
        n = len(text)
        blocks = self._blocks(columns, global_order, col_merge)
        block_count = len(blocks)

        if block_count == 0:
            return [[] for _ in range(n)]

        block_text = []
        block_mass = []

        for block in blocks:
            values = [
                "".join(text[row][column] for column in block)
                for row in range(n)
            ]
            block_text.append(values)

            counts = Counter(values)
            mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            block_mass.append(mass)

        ranked = sorted(
            range(block_count),
            key=lambda block: (
                -block_mass[block],
                len(blocks[block]),
                block,
            ),
        )
        candidates = ranked[:min(20, block_count)]

        result = [None] * n
        max_depth = min(8, block_count)
        node_limit = 384
        nodes = 0

        def finish(rows, prefix, remaining):
            """Complete a leaf with every unused atomic block in ranked order."""
            tail = [block for block in ranked if block in remaining]
            source_order = []

            for block in prefix + tail:
                source_order.extend(blocks[block])

            for row in rows:
                result[row] = source_order[:]

        def visit(rows, remaining, prefix, depth):
            """Select the strongest local block and recurse into its value groups."""
            nonlocal nodes
            nodes += 1

            available = [
                block for block in candidates
                if block in remaining
            ]

            if (
                len(rows) < 2
                or not available
                or depth >= max_depth
                or nodes > node_limit
            ):
                finish(rows, prefix, remaining)
                return

            best_block = -1
            best_score = 0
            best_groups = None

            for block in available:
                groups = defaultdict(list)
                values = block_text[block]

                for row in rows:
                    groups[values[row]].append(row)

                score = sum(
                    len(value) * len(members) * (len(members) - 1)
                    for value, members in groups.items()
                    if len(members) > 1
                )

                if (
                    score > best_score
                    or (
                        score == best_score
                        and score > 0
                        and (
                            best_block < 0
                            or block < best_block
                        )
                    )
                ):
                    best_block = block
                    best_score = score
                    best_groups = groups

            if best_block < 0 or best_score <= 0:
                finish(rows, prefix, remaining)
                return

            next_remaining = set(remaining)
            next_remaining.remove(best_block)

            children = sorted(
                best_groups.values(),
                key=lambda members: (-len(members), min(members)),
            )

            for members in children:
                visit(
                    members,
                    next_remaining,
                    prefix + [best_block],
                    depth + 1,
                )

        visit(list(range(n)), set(range(block_count)), [], 0)

        fallback = []
        for block in ranked:
            fallback.extend(blocks[block])

        for row in range(n):
            if result[row] is None:
                result[row] = fallback[:]

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded candidate and return valid reordered rows."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(m)]
            for row in range(n)
        ]

        global_orders, global_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_orders:
            orders = [order[:] for _ in range(n)]
            serial = self._strings(text, orders)
            candidates.append((self._reuse(serial), orders, serial))

        conditional_orders = self._conditional(
            text,
            columns,
            col_merge,
            global_order,
        )
        conditional_serial = self._strings(text, conditional_orders)
        candidates.append((
            self._reuse(conditional_serial),
            conditional_orders,
            conditional_serial,
        ))

        _, best_orders, best_serial = max(
            candidates,
            key=lambda candidate: candidate[0],
        )

        row_order = sorted(
            range(n),
            key=lambda row: best_serial[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

